frappe.ui.form.on('Project Tasks', {
    cost_estimated(frm, cdt, cdn) {
        calculate_all(cdt, cdn);
    },
    qty(frm, cdt, cdn) {
        calculate_all(cdt, cdn);
    },
    days(frm, cdt, cdn) {
        calculate_all(cdt, cdn);
    },
    margin(frm, cdt, cdn) {
        calculate_all(cdt, cdn);
    }
});

function calculate_all(cdt, cdn) {
    let row = locals[cdt][cdn];

    let cost_estimated = flt(row.cost_estimated);
    let qty = flt(row.qty);
    let days = flt(row.days);
    let margin_percent = flt(row.margin);  // % مثل 5 تعني 5%

    let margin = margin_percent / 100;

    // 1. total_cost
    let total_cost = cost_estimated * qty * days;

    // 2. item_mpricesales_price
    let item_mpricesales_price = (1 + margin) * cost_estimated;

    // 3. total_sales
    let total_sales = item_mpricesales_price * qty * days;

    // 4. vat
    let vat = total_sales * 0.15;

    // 5. total_cost2 = total_cost
    let total_cost2 = total_cost;

    // 6. total_margin = total_sales - total_cost
    let total_margin = total_sales - total_cost;

    // Set values
    frappe.model.set_value(cdt, cdn, 'total_cost', total_cost);
    frappe.model.set_value(cdt, cdn, 'item_mpricesales_price', item_mpricesales_price);
    frappe.model.set_value(cdt, cdn, 'total_sales', total_sales);
    frappe.model.set_value(cdt, cdn, 'vat', vat);
    frappe.model.set_value(cdt, cdn, 'total_cost2', total_cost2);
    frappe.model.set_value(cdt, cdn, 'total_margin', total_margin);
}

frappe.ui.form.on('Project Budget', {
    validate(frm) {
