    },
    project_tasks_on_form_rendered(frm) {
        calculate_task_totals(frm);
    },
    refresh(frm) {
        calculate_task_totals(frm);
    },
    task_type(frm) {
        // احسب من جديد عند تغيير نوع المهمة
        calculate_task_totals(frm);
    }
});

function calculate_task_totals(frm) {
    let selected_type = frm.doc.task_type;

    if (!selected_type) {
        // 🧼 تنظيف الحقول إذا النوع مش محدد
        frm.set_value('cost_estimated', 0);
        frm.set_value('sales_quotation', 0);
        frm.set_value('cost_profit', 0);
        return;
    }

    let total_cost_estimated = 0;
    let total_sales_quotation = 0;
    let total_cost_profit = 0;

    frm.doc.project_tasks.forEach(row => {
        if (row.task_type === selected_type) {
            total_cost_estimated += flt(row.total_cost);
            total_sales_quotation += flt(row.total_sales);
            total_cost_profit += flt(row.total_margin);
        }
    });

    frm.set_value('cost_estimated', total_cost_estimated);
    frm.set_value('sales_quotation', total_sales_quotation);
    frm.set_value('cost_profit', total_cost_profit);
}

frappe.ui.form.on('Project Budget', {
