            const items = (frm.doc.project_tasks || []).map(task => {
                const custom_qty = task.qty || 0;
                const custom_days = task.days || 0;
                const rate = task.item_mpricesales_price || 0;

                return {
                    item_code: task.item_code,
                    custom_custom_qty: custom_qty,
                    custom_custom_days: custom_days,
                    rate: rate,
                    qty: custom_qty * custom_days
                };
            });

            frappe.model.with_doctype('Quotation', async function () {
                const doc = frappe.model.get_new_doc('Quotation');
                doc.party_type = 'Customer';
                doc.party_name = frm.doc.client;
                doc.project = frm.doc.project;
                doc.transaction_date = frappe.datetime.get_today();

                frappe.set_route('Form', 'Quotation', doc.name);

                const waitForForm = () =>
                    new Promise(resolve => {
                        const check = () => {
                            if (cur_frm && cur_frm.docname === doc.name && cur_frm.doc.items) {
                                resolve();
                            } else {
                                setTimeout(check, 100);
                            }
                        };
                        check();
                    });

                await waitForForm();

                // 🟦 إضافة العناصر
                for (let item of items) {
                    const child = frappe.model.add_child(cur_frm.doc, 'Quotation Item', 'items');
                    await frappe.model.set_value(child.doctype, child.name, 'item_code', item.item_code);
                    frappe.model.set_value(child.doctype, child.name, 'custom_custom_qty', item.custom_custom_qty);
                    frappe.model.set_value(child.doctype, child.name, 'custom_custom_days', item.custom_custom_days);
                    frappe.model.set_value(child.doctype, child.name, 'rate', item.rate);
                    frappe.model.set_value(child.doctype, child.name, 'qty', item.qty);
                }

                // 🟨 إضافة الضرائب
                const tax1 = frappe.model.add_child(cur_frm.doc, 'Sales Taxes and Charges', 'taxes');
                tax1.charge_type = "Actual";
                tax1.account_head = frm.doc.account_headf;
                tax1.tax_amount = frm.doc.agency_fee;

                const tax2 = frappe.model.add_child(cur_frm.doc, 'Sales Taxes and Charges', 'taxes');
                tax2.charge_type = "Actual";
                tax2.account_head = frm.doc.account_headv;
                tax2.tax_amount = frm.doc.vat;

                cur_frm.refresh_fields();
            });
        });
    }
});

frappe.ui.form.on('Project Budget', {
    validate: function(frm) {
        const tasks = frm.doc.project_tasks || [];
        const checklist = frm.doc.checklist || [];

        // خريطة للمهام الموجودة
        const task_map = new Map();

        // 1. أضف أو عدّل في checklist
        tasks.forEach(task => {
            if (!task.task) return;

            task_map.set(task.task, true); // استخدمنا task كمفتاح

            const existing_row = checklist.find(row => row.task === task.task);
            if (existing_row) {
                existing_row.task_type = task.task_type;
                existing_row.qty = task.qty;
                existing_row.days = task.days;
            } else {
                frm.add_child("checklist", {
                    task: task.task,
                    task_type: task.task_type,
                    qty: task.qty,
                    days: task.days
                });
            }
        });

        // 2. حذف أي صف غير موجود
        frm.doc.checklist = checklist.filter(row => task_map.has(row.task));

        frm.refresh_field('checklist');
    }
});

