function calculate_totals(frm) {
    let total_sales_base = 0;
    let total_cost = 0;
    let total_margin = 0;

    (frm.doc.project_tasks || []).forEach(row => {
        total_sales_base += flt(row.total_sales);
        total_cost += flt(row.total_cost2);
        total_margin += flt(row.total_margin);
    });

    let agency_fee_percent = flt(frm.doc.agency_fee_percent || 0);
    let vat_percent = flt(frm.doc.vat_percent || 0);

    let agency_fee = total_sales_base * (agency_fee_percent / 100);
    let total_sales = total_sales_base + agency_fee;
    let vat = total_sales * (vat_percent / 100);
    let total_project = total_sales + vat;
    let margin = total_margin + agency_fee;

    frm.set_value('agency_fee', agency_fee);
    frm.set_value('total_sales', total_sales);
    frm.set_value('vat', vat);
    frm.set_value('total_project', total_project);
    frm.set_value('cost', total_cost);
    frm.set_value('margin', margin);

    frm.refresh_fields(['agency_fee', 'total_sales', 'vat', 'total_project', 'cost', 'margin']);
}

